const form = $('Webhook').first().json.body ?? {};
const gemini = $input.first().json;
const aiText = gemini.content?.parts?.[0]?.text;
if (!aiText) {
  throw new Error('Gemini output is missing content.parts[0].text');
}
const fields = ['degree', 'skill', 'experience', 'careerGoal', 'platforms', 'interest', 'availableTime', 'fiverrEnabled', 'serviceType', 'targetClient', 'tools', 'startingPrice', 'deliveryTime', 'revisions', 'portfolio'];
const row = { timestamp: new Date().toISOString(), aiResultJSON: aiText };
for (const field of fields) {
  row[field] = form[field] ?? '';
}
return [{ json: row }];
